gcf(){return"\u0412\u042b\u0421\u0422\u0423\u041f\u041b\u0415\u041d\u0418\u0415 \u0410\u041d\u0421\u0410\u041c\u0411\u041b\u042f"},
gcg(){return"\u0412\u043e\u0437\u044c\u043c\u0438\u0442\u0435 \u043d\u0430 \u0441\u0446\u0435\u043d\u0443 \u0432\u0441\u0435 \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043b\u0435\u043d\u043d\u044b\u0435 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u044b."},
gce(){return"\u0421\u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0441\u0435\u0442-\u043b\u0438\u0441\u0442 \u0438 \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u044c\u0442\u0435 \u0441\u0432\u043e\u0438 \u043f\u0430\u0440\u0442\u0438\u0442\u0443\u0440\u044b \u043f\u0435\u0440\u0435\u0434 \u0432\u044b\u0445\u043e\u0434\u043e\u043c \u043d\u0430 \u0441\u0446\u0435\u043d\u0443, \u0447\u0442\u043e\u0431\u044b \u0443\u0434\u0435\u043b\u0438\u0442\u044c \u0431\u043e\u043b\u044c\u0448\u0435 \u0432\u043d\u0438\u043c\u0430\u043d\u0438\u044f \u043c\u0443\u0437\u044b\u043a\u0435 \u0432\u043e\u043a\u0440\u0443\u0433 \u0432\u0430\u0441."},
